#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int totalstudents=3*n;
	    vector<long long >rating(totalstudents);
	    for(int i=0;i<totalstudents;i++){
	        cin>>rating[i];
	    }
	    sort(rating.begin(),rating.end(),greater<long long>());\
	    vector<long long>prefix(totalstudents+1,0);
	    for(int i=0;i<totalstudents;i++){\
	    prefix[i+1]=prefix[i]+rating[i];	}
	auto evaluate=[&](int soloteams,int pairteam){
	    int pairend=soloteams+2*pairteam;
	    int trioend=totalstudents-2*soloteams-pairteam;
	    return 2*prefix[soloteams]+prefix[pairend]+3*prefix[trioend];
	    
	};
	long long besttotal=0;
	for(int soloteams=0;soloteams<=n;soloteams++){
	    int low=0;
	    int high=n-soloteams;
	    while(high-low>2){
	        int leftmid=low+(high-low)/3;
	        int rightmid=high-(high-low)/3;
	        if(evaluate(soloteams,leftmid)<evaluate(soloteams,rightmid)){
	            low=leftmid+1;   }
	        else{
	            high=rightmid;
	        }
	    }   for(int pairteams=low;pairteams<=high;pairteams++){
	        besttotal=max(besttotal,evaluate(soloteams,pairteams));
	    }
	}
	cout<<besttotal<<"\n";
	}	return 0;
}
